// 地面（B、C 全程不落地）
Draw.ground(-2.0, 12.0, -30.0);

// 传送带：带面顶在 y=0，顺时针转动（带面刻度向右移）
Draw.belt([-1.5, 0], [7.0, 0], { r: 0.08, ticks: 26, tickPhase: t * 2 });

// 阶段边界参考线：x=1（与带共速）、x=6（剪断 B、C 间绳处）
Draw.line([1, 0], [1, 0.9], { dash: true, width: 1 });
Draw.line([6, 0], [6, 0.9], { dash: true, width: 1 });

// 定滑轮与它上方的固定支架（斜线阴影）
Draw.line([8.0, 0.05], [8.0, 0.6], { width: 2 });
Draw.ground(7.3, 8.7, 0.6);
Draw.pulley([8.0, 0.05], 0.2);

// 物块 A（置于传送带上）
Draw.box([state.A.x, state.A.y], state.A.w, state.A.h, { angleDeg: state.A.angleDeg });

// 轻绳：A 右端 → 滑轮左切点（水平段）
Draw.line([state.A.x + state.A.w / 2, state.A.y], [7.8, 0.05]);

// 悬挂物块 B、C
Draw.box([state.B.x, state.B.y], state.B.w, state.B.h);
Draw.box([state.C.x, state.C.y], state.C.w, state.C.h);

// 轻绳：滑轮右切点 → B 顶（竖直段）
Draw.line([8.2, 0.05], [state.B.x, state.B.y + state.B.h / 2]);

// 轻绳：B 底 → C 顶（竖直段）
Draw.line([state.B.x, state.B.y - state.B.h / 2], [state.C.x, state.C.y + state.C.h / 2]);

slots.readouts:
// 由 analysis 运动表生成；曲线图直接读这里
const out = [];
const h = 1e-4;
const tA = Math.max(0, t - h);
const tB = Math.min(3.5227, t + h);
const a = stateAt(tA);
const b = stateAt(tB);
const dt = (tB - tA) || 1;
out.push({ key: "A.x", label: "A 水平位置", value: state.A.x, unit: 'm' });
out.push({ key: "A.y", label: "A 竖直位置", value: state.A.y, unit: 'm' });
out.push({ key: "A.vx", label: "A 水平速度", value: (b.A.x - a.A.x) / dt, unit: 'm/s' });
out.push({ key: "A.vy", label: "A 竖直速度", value: (b.A.y - a.A.y) / dt, unit: 'm/s' });
out.push({ key: "B.x", label: "B 水平位置", value: state.B.x, unit: 'm' });
out.push({ key: "B.y", label: "B 竖直位置", value: state.B.y, unit: 'm' });
out.push({ key: "B.vx", label: "B 水平速度", value: (b.B.x - a.B.x) / dt, unit: 'm/s' });
out.push({ key: "B.vy", label: "B 竖直速度", value: (b.B.y - a.B.y) / dt, unit: 'm/s' });
out.push({ key: "C.x", label: "C 水平位置", value: state.C.x, unit: 'm' });
out.push({ key: "C.y", label: "C 竖直位置", value: state.C.y, unit: 'm' });
out.push({ key: "C.vx", label: "C 水平速度", value: (b.C.x - a.C.x) / dt, unit: 'm/s' });
out.push({ key: "C.vy", label: "C 竖直速度", value: (b.C.y - a.C.y) / dt, unit: 'm/s' });
return out;
